// Writes packages/api-types/openapi.yaml from the Zod schemas. `pnpm --filter @pontis/api-types generate`.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { stringify } from "yaml";
import { buildOpenApiDocument } from "../src/endpoints.ts";

const target = fileURLToPath(new URL("../openapi.yaml", import.meta.url));
export const HEADER =
  "# GENERATED by `pnpm --filter @pontis/api-types generate`. Do not edit by hand.\n";

writeFileSync(target, HEADER + stringify(buildOpenApiDocument(), { lineWidth: 0 }));
console.log(`wrote ${target}`);
